WITH base AS (SELECT *, DATE_TRUNC('YEAR', delivered_date) AS delivered_date_period FROM shipments WHERE delivered_date BETWEEN '2024-03-03' AND '2024-03-19'), remaining_keys AS (SELECT id, carrier FROM base INTERSECT SELECT id, carrier FROM shipments WHERE delivered_date BETWEEN '2025-09-02' AND '2025-10-01'), verified AS (SELECT s.* FROM base s INNER JOIN remaining_keys k ON s.id = k.id AND s.carrier = k.carrier), matched_keys AS (SELECT status, carrier FROM verified EXCEPT SELECT status, carrier FROM shipments WHERE order_id = 29), reconciled AS (SELECT s.* FROM verified s INNER JOIN matched_keys k ON s.status = k.status AND s.carrier = k.carrier), metrics AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, delivered_date_period, COUNT(cost) OVER (PARTITION BY carrier, status) AS carrier_count_cost, AVG(cost) OVER (PARTITION BY status ORDER BY CAST(delivered_date_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS cost_avg_30d, COUNT(cost) OVER (PARTITION BY order_id ORDER BY CAST(delivered_date_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS cost_count_30d FROM reconciled), scored AS (SELECT *, CUME_DIST() OVER (PARTITION BY order_id, carrier ORDER BY cost_avg_30d NULLS LAST) AS cost_avg_30d_cume_dist, COUNT(cost_count_30d) OVER (PARTITION BY order_id, carrier ORDER BY CAST(delivered_date_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS cost_count_30d_count_7d FROM metrics), valid AS (SELECT id, order_id, carrier, shipped_date, delivered_date, status, delivered_date_period, carrier_count_cost, cost_avg_30d_cume_dist, cost_count_30d_count_7d, GREATEST(carrier_count_cost, cost_avg_30d_cume_dist) AS greatest_carrier_count_cost_cost_avg_30d_cume_dist, COALESCE(carrier, 'UNKNOWN') AS carrier_clean FROM scored WHERE order_id IS NOT NULL) SELECT CASE WHEN cost_avg_30d_cume_dist >= 0.69 THEN 'LARGE' ELSE 'SMALL' END AS cost_avg_30d_cume_dist_tier, DATE_TRUNC('MONTH', shipped_date) AS activity_month, AVG(cost_count_30d_count_7d) AS avg_cost_count_30d_count_7d, ROUND(SUM(greatest_carrier_count_cost_cost_avg_30d_cume_dist) / NULLIF(COUNT(CASE WHEN carrier = 'FedEx' THEN 1 END), 0), 2) AS greatest_carrier_count_cost_cost_avg_30d_cume_dist_per_fedex, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM valid GROUP BY CASE WHEN cost_avg_30d_cume_dist >= 0.69 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', shipped_date) HAVING avg_cost_count_30d_count_7d >= 0
